using ECommerceSystem.InventoryService.Data.Entities;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace ECommerceSystem.InventoryService.Data.Configurations;

public class ProcessedMessageConfiguration : IEntityTypeConfiguration<ProcessedMessage>
{
    public void Configure(EntityTypeBuilder<ProcessedMessage> builder)
    {
        builder.ToTable("ProcessedMessages");

        builder.HasKey(m => m.MessageId);

        // The id comes from the message itself - never generated by EF or SQL Server.
        builder.Property(m => m.MessageId)
            .ValueGeneratedNever();

        builder.Property(m => m.Consumer)
            .IsRequired()
            .HasMaxLength(200);

        builder.Property(m => m.ProcessedAtUtc)
            .IsRequired();
    }
}